94: function pushFace(out, x, y, z, face, tile, scale = 1) {
95:   const uv = tileUV(tile); const tex = [[uv.u0,uv.v0],[uv.u0,uv.v1],[uv.u1,uv.v1],[uv.u1,uv.v0]];
96:   for (const i of TRI) {
97:     const p = face.v[i]; out.positions.push(x + p[0] * scale, y + p[1] * scale, z + p[2] * scale);
98:     out.normals.push(...face.n); out.uvs.push(...tex[i]);
