196: function generateQueuedChunk() {
197:   const next = loadingQueue.shift();
198:   if (!next) return false;
199:   const data = state.generator.generateChunk(next.cx, next.cz);
200:   const chunk = { ...data, group: null, cx: next.cx, cz: next.cz };
201:   state.chunks.set(next.key, chunk);
202:   for (const [position, id] of state.edits) {
203:     const [wx, y, wz] = position.split(',').map(Number);
204:     if (Math.floor(wx / 16) !== next.cx || Math.floor(wz / 16) !== next.cz || y < 0 || y >= WORLD_HEIGHT) continue;
205:     const lx = ((wx % 16) + 16) % 16, lz = ((wz % 16) + 16) % 16;
206:     chunk.blocks[(y << 8) | (lz << 4) | lx] = id;
207:   }
208:   rebuildChunk(next.cx, next.cz);
209:   if (getChunk(next.cx - 1, next.cz)) rebuildChunk(next.cx - 1, next.cz);
210:   if (getChunk(next.cx + 1, next.cz)) rebuildChunk(next.cx + 1, next.cz);
211:   if (getChunk(next.cx, next.cz - 1)) rebuildChunk(next.cx, next.cz - 1);
212:   if (getChunk(next.cx, next.cz + 1)) rebuildChunk(next.cx, next.cz + 1);
213:   return true;
214: }
