541: function buildAtlasData() {
542:   const px = ATLAS_SIZE;
543:   const albedoData = new Uint8ClampedArray(px * px * 4);
544:   const normalData = new Uint8ClampedArray(px * px * 4);
545:   const roughData = new Uint8ClampedArray(px * px * 4);
546: 
547:   for (let tile = 0; tile < 64; tile++) {
548:     const col = tile % ATLAS_COLS;
549:     const row = Math.floor(tile / ATLAS_COLS);
550:     const painter = P[tile];
551:     const colors = new Uint8ClampedArray(TILE_SIZE * TILE_SIZE * 4);
552:     const heights = new Float32Array(TILE_SIZE * TILE_SIZE);
553:     const roughs = new Float32Array(TILE_SIZE * TILE_SIZE);
554: 
555:     for (let y = 0; y < TILE_SIZE; y++) {
556:       for (let x = 0; x < TILE_SIZE; x++) {
557:         const u = (x + 0.5) / TILE_SIZE;
558:         const v = (y + 0.5) / TILE_SIZE;
559:         const out = painter(u, v);
560:         const i = y * TILE_SIZE + x;
561:         colors[i * 4] = out.c[0];
562:         colors[i * 4 + 1] = out.c[1];
563:         colors[i * 4 + 2] = out.c[2];
564:         colors[i * 4 + 3] = Math.round(clamp01(out.a) * 255);
565:         heights[i] = out.h;
566:         roughs[i] = out.r;
567:       }
568:     }
569: 
