89:   g.setAttribute('normal', new THREE.Float32BufferAttribute(arrays.normals, 3));
90:   g.setAttribute('uv', new THREE.Float32BufferAttribute(arrays.uvs, 2));
91:   g.computeBoundingSphere();
92:   return g;
