94: function pushFace(out, x, y, z, face, tile, scale = 1) {
95:   const uv = tileUV(tile); const tex = [[uv.u0,uv.v0],[uv.u0,uv.v1],[uv.u1,uv.v1],[uv.u1,uv.v0]];
96:   for (const i of TRI) {
97:     const p = face.v[i]; out.positions.push(x + p[0] * scale, y + p[1] * scale, z + p[2] * scale);
98:     out.normals.push(...face.n); out.uvs.push(...tex[i]);
99:   }
100: }
101: function pushPlant(out, x, y, z, tile) {
102:   const uv = tileUV(tile); const a = [[uv.u0,uv.v0],[uv.u0,uv.v1],[uv.u1,uv.v1],[uv.u1,uv.v0]];
103:   for (const rot of [0, Math.PI / 2]) for (const flip of [false, true]) {
104:     for (const i of TRI) {
105:       let px = [0.12,0.12,0.88,0.88][i], pz = [0.12,0.88,0.88,0.12][i];
106:       if (flip) px = 1 - px;
107:       const rx = px - 0.5, rz = pz - 0.5;
108:       const vx = 0.5 + rx * Math.cos(rot) - rz * Math.sin(rot), vz = 0.5 + rx * Math.sin(rot) + rz * Math.cos(rot);
109:       out.positions.push(x + vx, y + (i === 1 || i === 2 ? 0.95 : 0.02), z + vz);
110:       out.normals.push(0, 0.7, 0); out.uvs.push(...a[i]);
111:     }
112:   }
113: }
114: function visibleAgainst(id, other) {
115:   if (other === 0 || BLOCKS[other]?.plant) return true;
116:   if (id === BLOCK_IDS.water) return other !== BLOCK_IDS.water;
117:   if (BLOCKS[id]?.render === 'glass') return other !== id && other !== BLOCK_IDS.glass;
118:   return !BLOCKS[other]?.opaque;
119: }
