121: function rebuildChunk(cx, cz) {
122:   const c = getChunk(cx, cz); if (!c) return;
123:   if (c.group) { worldRoot.remove(c.group); c.group.traverse(o => { if (o.geometry) o.geometry.dispose(); }); }
124:   const group = new THREE.Group(); group.position.set(cx * 16, 0, cz * 16); c.group = group;
125:   const opaque = { positions: [], normals: [], uvs: [] }, transparent = { positions: [], normals: [], uvs: [] }, plants = { positions: [], normals: [], uvs: [] };
126:   for (let y = 0; y < WORLD_HEIGHT; y++) for (let z = 0; z < 16; z++) for (let x = 0; x < 16; x++) {
127:     const id = c.blocks[(y << 8) | (z << 4) | x]; if (!id) continue;
128:     const def = BLOCKS[id];
129:     if (def.plant) { pushPlant(plants, x, y, z, def.tiles.all ?? def.tiles.side); continue; }
130:     const out = id === BLOCK_IDS.water || def.render === 'glass' ? transparent : opaque;
131:     for (const face of FACE_DATA) {
132:       const other = getBlock(cx * 16 + x + face.n[0], y + face.n[1], cz * 16 + z + face.n[2]);
133:       if (visibleAgainst(id, other)) pushFace(out, x, y, z, face, def.tiles[face.side] ?? def.tiles.side);
134:     }
135:   }
136:   const geo = makeGeometry(opaque);
137:   if (geo) { const mesh = new THREE.Mesh(geo, worldMat); mesh.castShadow = true; mesh.receiveShadow = true; group.add(mesh); }
138:   const transGeo = makeGeometry(transparent);
139:   if (transGeo) {
140:     const waterGeo = new THREE.BufferGeometry(), glassGeo = new THREE.BufferGeometry();
141:     // Keep water and glass separated to preserve distinct optical response.
142:     const water = { positions: [], normals: [], uvs: [] }, glass = { positions: [], normals: [], uvs: [] };
143:     for (let y = 0; y < WORLD_HEIGHT; y++) for (let z = 0; z < 16; z++) for (let x = 0; x < 16; x++) {
144:       const id = c.blocks[(y << 8) | (z << 4) | x]; if (id !== BLOCK_IDS.water && BLOCKS[id]?.render !== 'glass') continue;
145:       const out = id === BLOCK_IDS.water ? water : glass, def = BLOCKS[id];
146:       for (const face of FACE_DATA) { const other = getBlock(cx*16+x+face.n[0], y+face.n[1], cz*16+z+face.n[2]); if (visibleAgainst(id, other)) pushFace(out,x,y,z,face,def.tiles[face.side] ?? def.tiles.side); }
147:     }
148:     waterGeo.copy(makeGeometry(water) || new THREE.BufferGeometry()); glassGeo.copy(makeGeometry(glass) || new THREE.BufferGeometry());
149:     if (water.positions.length) { const m = new THREE.Mesh(waterGeo, waterMat); m.renderOrder = 2; group.add(m); }
150:     if (glass.positions.length) { const m = new THREE.Mesh(glassGeo, glassMat); m.renderOrder = 3; group.add(m); }
151:     transGeo.dispose();
152:   }
153:   const plantGeo = makeGeometry(plants);
154:   if (plantGeo) { const m = new THREE.Mesh(plantGeo, plantMat); m.castShadow = true; group.add(m); }
155:   worldRoot.add(group);
156: }
