189: function queueChunk(cx, cz) {
190:   const key = chunkKey(cx, cz);
191:   if (state.chunks.has(key) || loadingQueue.some((item) => item.key === key)) return;
192:   loadingQueue.push({ cx, cz, key, distance: Math.max(Math.abs(cx - Math.floor(state.x / 16)), Math.abs(cz - Math.floor(state.z / 16))) });
193:   loadingQueue.sort((a, b) => a.distance - b.distance);
194: }
