219:   for (let r = 0; r <= distance; r++) {
220:     for (let z = -r; z <= r; z++) for (let x = -r; x <= r; x++) {
221:       if (Math.max(Math.abs(x), Math.abs(z)) !== r) continue;
222:       queueChunk(cx + x, cz + z);
223:     }
224:   }
225:   const unloadDistance = distance + 2;
226:   for (const [key, chunk] of state.chunks) {
227:     if (Math.max(Math.abs(chunk.cx - cx), Math.abs(chunk.cz - cz)) <= unloadDistance) continue;
228:     worldRoot.remove(chunk.group);
229:     chunk.group?.traverse((object) => object.geometry?.dispose());
230:     state.chunks.delete(key);
231:   }
232: }
