311: function findTarget() {
312:   const direction = new THREE.Vector3();
313:   camera.getWorldDirection(direction);
314:   let x = Math.floor(camera.position.x), y = Math.floor(camera.position.y), z = Math.floor(camera.position.z);
315:   const stepX = Math.sign(direction.x), stepY = Math.sign(direction.y), stepZ = Math.sign(direction.z);
316:   const deltaX = stepX ? Math.abs(1 / direction.x) : Infinity;
317:   const deltaY = stepY ? Math.abs(1 / direction.y) : Infinity;
318:   const deltaZ = stepZ ? Math.abs(1 / direction.z) : Infinity;
319:   let maxX = stepX > 0 ? (x + 1 - camera.position.x) * deltaX : (camera.position.x - x) * deltaX;
320:   let maxY = stepY > 0 ? (y + 1 - camera.position.y) * deltaY : (camera.position.y - y) * deltaY;
321:   let maxZ = stepZ > 0 ? (z + 1 - camera.position.z) * deltaZ : (camera.position.z - z) * deltaZ;
322:   let previous = null;
323:   for (let distance = 0; distance <= 7; distance++) {
324:     const id = getBlock(x, y, z);
325:     if (id && id !== BLOCK_IDS.water && !getBlockDef(id).plant) return { x, y, z, id, previous };
326:     previous = { x, y, z };
327:     if (maxX < maxY && maxX < maxZ) { x += stepX; distance = maxX; maxX += deltaX; }
328:     else if (maxY < maxZ) { y += stepY; distance = maxY; maxY += deltaY; }
329:     else { z += stepZ; distance = maxZ; maxZ += deltaZ; }
330:   }
331:   return null;
332: }
