409: function collideAt(x, y, z) {
410:   const minX = Math.floor(x - playerRadius), maxX = Math.floor(x + playerRadius);
411:   const minY = Math.floor(y + 0.02), maxY = Math.floor(y + playerHeight - 0.03);
412:   const minZ = Math.floor(z - playerRadius), maxZ = Math.floor(z + playerRadius);
413:   for (let by = minY; by <= maxY; by++) for (let bz = minZ; bz <= maxZ; bz++) for (let bx = minX; bx <= maxX; bx++) {
414:     const id = getBlock(bx, by, bz);
415:     if (isSolid(id) && !getBlockDef(id).plant) return true;
416:   }
