420: function movePlayer(dt) {
421:   const forward = (state.keys.has('KeyW') || state.move.z < -0.15 ? 1 : 0) - (state.keys.has('KeyS') || state.move.z > 0.15 ? 1 : 0);
422:   const strafe = (state.keys.has('KeyD') || state.move.x > 0.15 ? 1 : 0) - (state.keys.has('KeyA') || state.move.x < -0.15 ? 1 : 0);
423:   const sprint = state.keys.has('ShiftLeft') || state.keys.has('ShiftRight');
424:   const speed = state.flying ? (sprint ? 12 : 7) : (sprint ? 7.3 : 4.7);
425:   const length = Math.hypot(forward, strafe) || 1;
426:   const dx = (Math.sin(state.yaw) * forward + Math.cos(state.yaw) * strafe) * speed * dt / length;
427:   const dz = (-Math.cos(state.yaw) * forward + Math.sin(state.yaw) * strafe) * speed * dt / length;
428:   const nx = state.x + dx;
429:   if (!collideAt(nx, state.y, state.z)) state.x = nx;
430:   const nz = state.z + dz;
431:   if (!collideAt(state.x, state.y, nz)) state.z = nz;
432: 
433:   const jumping = state.keys.has('Space') || state.touchJump;
434:   if (state.flying) {
435:     const vertical = (jumping ? 1 : 0) - (state.keys.has('ControlLeft') || state.keys.has('ControlRight') ? 1 : 0);
436:     state.y += vertical * speed * dt;
437:     state.vy = 0; state.grounded = false;
438:   } else {
439:     if (jumping && state.grounded) { state.vy = 8.2; state.grounded = false; }
440:     state.vy -= 23 * dt;
441:     const ny = state.y + state.vy * dt;
442:     if (!collideAt(state.x, ny, state.z)) { state.y = ny; state.grounded = false; }
443:     else {
444:       if (state.vy < 0) state.grounded = true;
445:       state.vy = 0;
446:     }
447:   }
448:   if (state.y < -8) {
449:     state.y = state.spawn.y; state.x = state.spawn.x + 0.5; state.z = state.spawn.z + 0.5; state.vy = 0;
450:     showToast('Returned to your starting point');
451:   }
452:   camera.position.set(state.x, state.y + 1.62, state.z);
453:   camera.rotation.set(state.pitch, state.yaw, 0);
454: }
