27:   [BIOME.ocean]: { name: 'Open Water', tint: [0.8, 0.95, 0.8] },
28:   [BIOME.beach]: { name: 'Shoreline', tint: [1.0, 0.98, 0.82] },
29:   [BIOME.meadow]: { name: 'Meadow', tint: [1.02, 1.06, 0.85] },
30:   [BIOME.forest]: { name: 'Deep Forest', tint: [0.82, 0.97, 0.72] },
31:   [BIOME.birch]: { name: 'Birch Grove', tint: [1.03, 1.08, 0.82] },
32:   [BIOME.desert]: { name: 'Dunes', tint: [1.1, 1.0, 0.7] },
33:   [BIOME.taiga]: { name: 'Taiga', tint: [0.76, 0.92, 0.76] },
