39: const COAL = BLOCK_IDS.coal_ore;
40: const IRON = BLOCK_IDS.iron_ore;
41: const ICE = BLOCK_IDS.ice;
42: const CACTUS = BLOCK_IDS.cactus;
43: const MOSSY = BLOCK_IDS.mossy_stone;
44: const PINE = LEAVES_PINE;
45: const FERN = BLOCK_IDS.fern;
46: const FLOWER_RED = BLOCK_IDS.flower_red;
47: const FLOWER_YELLOW = BLOCK_IDS.flower_yellow;
48: const DEAD_BUSH = BLOCK_IDS.dead_bush;
49: const MUSHROOM_RED = BLOCK_IDS.mushroom_red;
50: 
51: function idx(x, y, z) {
52:   return (y << 8) | (z << 4) | x;
53: }
54: 
55: export class WorldGenerator {
56:   constructor(seed = 1337) {
57:     this.seed = seed >>> 0;
58:     this.perlin = new Perlin(this.seed);
59:     this.tex = new Perlin((this.seed ^ 0x9e3779b9) >>> 0);
60:     this.moist = new Perlin((this.seed ^ 0x85ebca6b) >>> 0);
61:     this.misc = new Perlin((this.seed ^ 0xc2b2ae35) >>> 0);
62:     this.cache = new Map();
63:     this.spawn = null;
64:   }
65: 
66:   rawHeight(x, z) {
67:     const p = this.perlin;
68:     const continental = p.fbm2(x * 0.0018, z * 0.0018, 4, 2.03, 0.52);
69:     const hills = p.fbm2(x * 0.017 + 31, z * 0.017 - 17, 4, 2.1, 0.48);
70:     const ridge = p.ridged2(x * 0.0042 + 7.3, z * 0.0042 - 3.1, 4);
71:     const detail = p.noise2(x * 0.085, z * 0.085);
72:     const mountainMask = smoothstep(0.02, 0.55, continental + ridge * 0.28 - 0.05);
73:     let h = SEA_LEVEL + 2 + continental * 17 + hills * 4.5 + detail * 1.1;
74:     h += mountainMask * Math.pow(ridge, 1.55) * 32;
75: 
76:     // River valleys, gently incised into lowlands.
77:     const riverNoise = Math.abs(p.fbm2(x * 0.0013 + 120.5, z * 0.0013 - 50.5, 3, 2.0, 0.55));
78:     const riverMask = smoothstep(0.065, 0.008, riverNoise) * smoothstep(SEA_LEVEL - 3, SEA_LEVEL + 14, h);
79:     h -= riverMask * 8;
80: 
81:     // Flatten beaches and the immediate shoreline a touch.
82:     const shoreBand = smoothstep(SEA_LEVEL + 5, SEA_LEVEL - 2, h);
83:     h = mix(h, SEA_LEVEL + 1.0, shoreBand * 0.22);
84:     return h;
85:   }
86: 
87:   column(x, z) {
88:     const key = `${x},${z}`;
89:     let c = this.cache.get(key);
90:     if (c) return c;
91:     const raw = this.rawHeight(x, z);
92:     const h = clamp(Math.round(raw), 2, WORLD_HEIGHT - 12);
93: 
94:     const temp = this.tex.fbm2(x * 0.0011 + 500, z * 0.0011 - 90, 3, 2.0, 0.55)
95:       - Math.max(0, h - SEA_LEVEL - 10) * 0.006;
96:     const moist = this.moist.fbm2(x * 0.0013 - 220, z * 0.0013 + 170, 3, 2.0, 0.55);
97:     const slope = Math.abs(this.rawHeight(x + 2, z) - this.rawHeight(x - 2, z))
98:       + Math.abs(this.rawHeight(x, z + 2) - this.rawHeight(x, z - 2));
99: 
100:     let biome;
101:     if (h < SEA_LEVEL - 1) biome = BIOME.ocean;
102:     else if (h <= SEA_LEVEL + 2) biome = BIOME.beach;
103:     else if (h > 66) biome = BIOME.snow;
104:     else if (h > 58) biome = BIOME.alpine;
105:     else if (temp < -0.18) biome = moist > 0.02 ? BIOME.taiga : BIOME.snow;
106:     else if (temp > 0.2 && moist < -0.08) biome = BIOME.desert;
107:     else if (moist > 0.13) biome = BIOME.forest;
108:     else if (moist > 0.02) biome = fi_birch(x, z) ? BIOME.birch : BIOME.forest;
109:     else if (moist < -0.16 && temp > 0.02) biome = BIOME.swamp;
110:     else biome = BIOME.meadow;
111: 
112:     // Surface material selection
113:     let surface = GRASS;
114:     let sub = DIRT;
115:     if (biome === BIOME.ocean) {
116:       surface = h < SEA_LEVEL - 7 ? GRAVEL : SAND;
117:       sub = CLAY;
118:     } else if (biome === BIOME.beach) {
119:       surface = SAND;
120:       sub = SANDSTONE;
121:     } else if (biome === BIOME.desert) {
122:       surface = SAND;
123:       sub = SANDSTONE;
124:     } else if (biome === BIOME.snow) {
125:       surface = h > 72 ? SNOW : SNOW_GRASS;
126:       sub = DIRT;
127:     } else if (biome === BIOME.alpine) {
128:       surface = slope > 5 ? STONE : (hash2(x, z, this.seed + 3) > 0.4 ? SNOW_GRASS : STONE);
129:       sub = STONE;
130:     } else if (biome === BIOME.taiga) {
131:       surface = moist > 0.12 ? SNOW_GRASS : GRASS;
132:       sub = DIRT;
133:     }
134:     if (slope > 8 && h > SEA_LEVEL + 3 && biome !== BIOME.desert) {
135:       surface = hash2(x, z, this.seed + 9) > 0.35 ? STONE : MOSSY;
136:       sub = STONE;
137:     }
138:     if (biome === BIOME.swamp && h <= SEA_LEVEL + 2) { surface = GRASS; sub = CLAY; }
139: 
140:     c = { x, z, h, raw, biome, temp, moist, slope, surface, sub };
141:     if (this.cache.size > 300000) this.cache.clear();
142:     this.cache.set(key, c);
143:     return c;
144:   }
145: 
146:   heightAt(x, z) {
147:     return this.column(x, z).h;
148:   }
149: 
150:   biomeAt(x, z) {
151:     return this.column(x, z).biome;
152:   }
153: 
154:   treeDensity(biome) {
155:     switch (biome) {
156:       case BIOME.forest: return 0.024;
157:       case BIOME.birch: return 0.018;
158:       case BIOME.taiga: return 0.024;
159:       case BIOME.meadow: return 0.004;
160:       case BIOME.swamp: return 0.012;
161:       case BIOME.snow: return 0.0025;
162:       case BIOME.desert: return 0;
163:       default: return 0.0008;
164:     }
165:   }
166: 
167:   // -------------------------------------------------------------------------
168:   // Chunk generation
169:   // -------------------------------------------------------------------------
170:   generateChunk(cx, cz) {
171:     const blocks = new Uint8Array(CHUNK_SIZE * CHUNK_SIZE * WORLD_HEIGHT);
172:     const heights = new Uint8Array(CHUNK_SIZE * CHUNK_SIZE);
173:     const biomes = new Uint8Array(CHUNK_SIZE * CHUNK_SIZE);
174:     const ox = cx * CHUNK_SIZE, oz = cz * CHUNK_SIZE;
175: 
176:     for (let z = 0; z < CHUNK_SIZE; z++) {
177:       for (let x = 0; x < CHUNK_SIZE; x++) {
178:         const wx = ox + x, wz = oz + z;
179:         const col = this.column(wx, wz);
180:         const h = col.h;
181:         heights[z * CHUNK_SIZE + x] = h;
182:         biomes[z * CHUNK_SIZE + x] = col.biome;
183: 
184:         // Bedrock floor
185:         blocks[idx(x, 0, z)] = BEDROCK;
186:         blocks[idx(x, 1, z)] = BEDROCK;
187:         if (hash3(wx, 2, wz, this.seed) > 0.6) blocks[idx(x, 2, z)] = BEDROCK;
188: 
189:         // Stone core + sparse ore veins
190:         for (let y = 2; y <= h - 3; y++) {
191:           let id = STONE;
192:           const o = hash3(wx, y, wz, this.seed + 11);
193:           if (y < 48) {
194:             if (o < 0.0075) id = COAL;
195:             else if (o < 0.0105) id = IRON;
196:           }
197:           blocks[idx(x, y, z)] = id;
198:         }
199: 
200:         // Sub-surface and surface
201:         const subDepth = col.biome === BIOME.desert || col.biome === BIOME.beach ? 5 : 3;
202:         blocks[idx(x, h, z)] = col.surface;
203:         for (let d = 1; d <= subDepth && h - d > 1; d++) {
204:           blocks[idx(x, h - d, z)] = d === 1 && col.surface === GRASS ? DIRT : col.sub;
205:         }
206:         if (col.biome === BIOME.snow && h > 70) {
207:           blocks[idx(x, h, z)] = SNOW;
208:           blocks[idx(x, h - 1, z)] = SNOW;
209:         }
210: 
211:         // Water / ice
212:         if (h < SEA_LEVEL) {
213:           for (let y = h + 1; y <= SEA_LEVEL; y++) blocks[idx(x, y, z)] = WATER;
214:           if (col.temp < -0.2 && h < SEA_LEVEL - 1) blocks[idx(x, SEA_LEVEL, z)] = ICE;
215:         }
216:       }
217:     }
218: 
219:     // Trees and large features (scan a margin so canopies cross chunk edges).
220:     for (let wz = oz - 3; wz < oz + CHUNK_SIZE + 3; wz++) {
221:       for (let wx = ox - 3; wx < ox + CHUNK_SIZE + 3; wx++) {
222:         const col = this.column(wx, wz);
223:         if (col.h <= SEA_LEVEL + 1) continue;
224:         const hh = hash2(wx, wz, this.seed + 31);
225:         const density = this.treeDensity(col.biome);
226:         if (hh < density) {
227:           this.placeTree(blocks, ox, oz, wx, wz, col);
228:         } else if (col.biome === BIOME.desert && hh > 0.996) {
229:           this.placeCactus(blocks, ox, oz, wx, wz, col.h + 1);
230:         } else if (hh > 0.9985 && (col.biome === BIOME.meadow || col.biome === BIOME.alpine)) {
231:           this.placeBoulder(blocks, ox, oz, wx, wz, col.h + 1);
232:         }
233:       }
234:     }
235: 
236:     // Ground cover
237:     for (let z = 0; z < CHUNK_SIZE; z++) {
238:       for (let x = 0; x < CHUNK_SIZE; x++) {
239:         const wx = ox + x, wz = oz + z;
240:         const h = heights[z * CHUNK_SIZE + x];
241:         if (h < SEA_LEVEL || h >= WORLD_HEIGHT - 2) continue;
242:         const top = blocks[idx(x, h, z)];
243:         const above = blocks[idx(x, h + 1, z)];
244:         if (above !== AIR) continue;
245:         const biome = biomes[z * CHUNK_SIZE + x];
246:         const r = hash2(wx, wz, this.seed + 77);
247: 
248:         if (top === GRASS || top === SNOW_GRASS) {
249:           if (biome === BIOME.forest || biome === BIOME.birch) {
250:             if (r < 0.12) blocks[idx(x, h + 1, z)] = r < 0.06 ? FERN : TALL_GRASS;
251:             else if (r < 0.128) blocks[idx(x, h + 1, z)] = hash2(wx, wz, 5) > 0.5 ? FLOWER_RED : FLOWER_YELLOW;
252:             else if (r > 0.996) blocks[idx(x, h + 1, z)] = MUSHROOM_RED;
253:           } else if (biome === BIOME.meadow) {
254:             if (r < 0.2) blocks[idx(x, h + 1, z)] = TALL_GRASS;
255:             else if (r < 0.225) blocks[idx(x, h + 1, z)] = hash2(wx, wz, 7) > 0.5 ? FLOWER_YELLOW : FLOWER_RED;
256:           } else if (biome === BIOME.taiga || biome === BIOME.swamp) {
257:             if (r < 0.1) blocks[idx(x, h + 1, z)] = r < 0.05 ? FERN : TALL_GRASS;
258:           } else if (r < 0.025) {
259:             blocks[idx(x, h + 1, z)] = TALL_GRASS;
260:           }
261:           // Rock outcrops
262:           if (biome === BIOME.alpine && r > 0.94) blocks[idx(x, h + 1, z)] = MOSSY;
263:         } else if (top === SAND && biome === BIOME.desert && r > 0.997) {
264:           blocks[idx(x, h + 1, z)] = DEAD_BUSH;
265:         }
266:       }
267:     }
268: 
269:     return { blocks, heights, biomes };
270:   }
271: 
272:   setLocal(blocks, ox, oz, wx, wy, wz, id, force = false) {
273:     const lx = wx - ox, lz = wz - oz;
274:     if (lx < 0 || lx >= CHUNK_SIZE || lz < 0 || lz >= CHUNK_SIZE || wy < 0 || wy >= WORLD_HEIGHT) return;
275:     const i = idx(lx, wy, lz);
276:     if (force || blocks[i] === AIR || blocks[i] === WATER || blocks[i] === TALL_GRASS) blocks[i] = id;
277:   }
278: 
279:   placeTree(blocks, ox, oz, wx, wz, col) {
280:     const r = hash2(wx, wz, this.seed + 131);
281:     const biome = col.biome;
282:     let trunkH = 4 + Math.floor(r * 3);
283:     let leafId = LEAVES_OAK;
284:     let logId = LOG_OAK;
285:     let pine = false;
286:     if (biome === BIOME.birch) { trunkH = 5 + Math.floor(r * 3); leafId = LEAVES_BIRCH; logId = LOG_BIRCH; }
287:     else if (biome === BIOME.taiga || biome === BIOME.snow) { trunkH = 6 + Math.floor(r * 4); leafId = PINE; logId = LOG_OAK; pine = true; }
288:     else if (biome === BIOME.swamp) { trunkH = 4 + Math.floor(r * 2); leafId = LEAVES_OAK; }
289:     const baseY = col.h + 1;
290: 
291:     for (let i = 0; i < trunkH; i++) this.setLocal(blocks, ox, oz, wx, baseY + i, wz, logId, true);
292: 
293:     if (pine) {
294:       const layers = Math.floor(trunkH * 0.85);
295:       for (let l = 0; l < layers; l++) {
296:         const y = baseY + trunkH - 2 - l;
297:         const radius = Math.max(0, Math.floor((l / layers) * 3.1));
298:         for (let dz = -radius; dz <= radius; dz++) {
299:           for (let dx = -radius; dx <= radius; dx++) {
300:             if (Math.abs(dx) + Math.abs(dz) > radius + 0.5) continue;
301:             if (dx === 0 && dz === 0 && y < baseY + trunkH) continue;
302:             this.setLocal(blocks, ox, oz, wx + dx, y, wz + dz, leafId);
303:           }
304:         }
305:       }
306:       this.setLocal(blocks, ox, oz, wx, baseY + trunkH, wz, leafId);
307:     } else {
308:       const topY = baseY + trunkH;
309:       const radius = 2 + (r > 0.62 ? 1 : 0);
310:       for (let dy = -2; dy <= 2; dy++) {
311:         const rr = radius - Math.max(0, Math.abs(dy) - 1) * 0.7;
312:         for (let dz = -radius; dz <= radius; dz++) {
313:           for (let dx = -radius; dx <= radius; dx++) {
314:             const d = Math.sqrt(dx * dx + dz * dz + dy * dy * 1.4);
315:             if (d > rr + 0.2) continue;
316:             if (dx === 0 && dz === 0 && dy <= 0) continue;
317:             if (hash3(wx + dx, topY + dy, wz + dz, this.seed + 5) < 0.08) continue;
318:             this.setLocal(blocks, ox, oz, wx + dx, topY + dy, wz + dz, leafId);
319:           }
320:         }
321:       }
322:       // A couple of limbs
323:       if (r > 0.4) {
324:         this.setLocal(blocks, ox, oz, wx + 1, baseY + trunkH - 2, wz, logId);
325:         this.setLocal(blocks, ox, oz, wx - 1, baseY + trunkH - 3, wz + 1, logId);
326:       }
327:     }
328:   }
329: 
330:   placeCactus(blocks, ox, oz, wx, wz, y) {
331:     const h = 1 + Math.floor(hash2(wx, wz, this.seed + 17) * 3);
332:     for (let i = 0; i < h; i++) this.setLocal(blocks, ox, oz, wx, y + i, wz, CACTUS, true);
333:   }
334: 
335:   placeBoulder(blocks, ox, oz, wx, wz, y) {
336:     const r = 1.4 + hash2(wx, wz, this.seed + 71) * 1.3;
337:     const mossy = hash2(wx, wz, this.seed + 72) > 0.45;
338:     for (let dy = -1; dy <= 2; dy++) {
339:       for (let dz = -2; dz <= 2; dz++) {
340:         for (let dx = -2; dx <= 2; dx++) {
341:           if (Math.sqrt(dx * dx + dz * dz + dy * dy * 1.5) > r) continue;
342:           this.setLocal(blocks, ox, oz, wx + dx, y + dy, wz + dz, mossy && dy > 0 ? MOSSY : STONE);
343:         }
344:       }
345:     }
346:   }
347: 
348:   // -------------------------------------------------------------------------
349:   // Spawn: find a scenic, walkable overlook near water and mountains.
350:   // -------------------------------------------------------------------------
351:   findSpawn() {
352:     if (this.spawn) return this.spawn;
353:     let best = null;
354:     let bestScore = -Infinity;
355:     for (let radius = 0; radius <= 150; radius += 9) {
356:       const steps = radius === 0 ? 1 : Math.max(12, Math.floor(radius * 0.7));
357:       for (let i = 0; i < steps; i++) {
358:         const a = (i / steps) * Math.PI * 2 + radius * 0.37;
359:         const x = Math.round(Math.cos(a) * radius + 6);
360:         const z = Math.round(Math.sin(a) * radius - 4);
361:         const col = this.column(x, z);
362:         if (col.h < SEA_LEVEL + 4 || col.h > SEA_LEVEL + 21) continue;
363:         if (col.slope > 7) continue;
364:         if (col.biome === BIOME.desert || col.biome === BIOME.ocean || col.biome === BIOME.beach) continue;
365: 
366:         // Flat enough to stand on
367:         let flat = 0;
368:         for (const [dx, dz] of [[3, 0], [-3, 0], [0, 3], [0, -3], [5, 5], [-5, -5]]) {
369:           flat += Math.abs(this.column(x + dx, z + dz).h - col.h);
370:         }
371:         if (flat > 14) continue;
372: 
373:         // Prefer a view over water and mountains in opposite-ish directions.
374:         let water = 0, mountains = 0, bestWaterAngle = 0;
375:         for (let a2 = 0; a2 < Math.PI * 2; a2 += Math.PI / 10) {
376:           const dx = Math.cos(a2), dz = Math.sin(a2);
377:           for (let d = 16; d <= 70; d += 8) {
378:             const hh = this.column(x + Math.round(dx * d), z + Math.round(dz * d)).h;
379:             if (hh < SEA_LEVEL - 1) { water += 34 - Math.min(34, Math.abs(d - 38)) * 0.4; bestWaterAngle = a2; break; }
380:             if (hh > col.h + 12) { mountains += Math.max(0, hh - 52) * 0.5; break; }
381:           }
382:         }
383:         const score = water * 0.85 + mountains * 0.6 - flat * 2.2 + (col.h - SEA_LEVEL) * 0.7
384:           + (col.biome === BIOME.forest || col.biome === BIOME.birch ? 6 : 0);
385:         if (score > bestScore) {
386:           bestScore = score;
387:           best = { x, z, y: col.h + 1, yaw: Math.atan2(-Math.cos(bestWaterAngle), -Math.sin(bestWaterAngle)), biome: col.biome, score };
388:         }
389:       }
390:       if (best && radius > 90) break;
391:     }
392:     if (!best) {
393:       const col = this.column(0, 0);
394:       best = { x: 0, z: 0, y: col.h + 1, yaw: Math.PI * 0.25, biome: col.biome, score: 0 };
395:     }
396:     this.spawn = best;
397:     return best;
398:   }
399: }
400: 
401: function fi_birch(x, z) {
402:   return hash2(Math.floor(x / 32), Math.floor(z / 32), 4242) > 0.55;
403: }
